contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function: caller provides an external recipient and an amount to fund this tester
    // The rule: if msg.sender is not the owner, calling sudicideAnyone must not transfer c's balance to msg.sender.
    function runTest(address caller, uint256 fundAmount) public payable {
        // require this test contract has enough balance to fund the contract c if needed
        require(address(this).balance >= fundAmount, "insufficient balance for funding");

        // record c balance before
        uint256 before = address(c).balance;

        // If fundAmount > 0, send Ether to c by calling nothing (we can't call payable functions on c because none exist),
        // but we can force-send by using selfdestruct pattern is not allowed; instead this step is optional — keep as no-op.
        // The distinguishing action is calling sudicideAnyone. We will call it and observe whether c's balance moved to caller.

        // Attempt to call sudicideAnyone as this contract but targeted to simulate caller: we cannot change msg.sender when calling c.
        // So to reflect the general rule we use the externally observable effect: when non-owner calls sudicideAnyone, c should not send its balance to msg.sender.
        // We require that caller is not the owner by reading public smartfix_owner getter.

        address owner = c.smartfix_owner();
        require(caller != owner, "choose caller different from owner to test restriction");

        // Now call sudicideAnyone from this contract. The distinguishing behavior depends on whether the contract enforces only-owner.
        // If only-owner is required, this call will revert (since this contract is not owner) and c's balance remains unchanged.
        // If require was removed, the call will succeed and selfdestruct c, sending c's balance to address(this) because msg.sender is this contract.
        bool success;
        // perform low-level call to capture revert boolean without bubbling
        (success, ) = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));

        uint256 after = address(c).balance;

        // Assert that either the call reverted (success == false) or, if it succeeded, the c's balance did not decrease (no transfer out).
        // For the original P, non-owner call reverts -> success==false and after==before, so condition holds.
        // For mutant M, non-owner call succeeds and selfdestruct transfers funds away -> after < before, violating the assertion.
        assert(success == false || after >= before);
    }

    // Allow contract to receive funds for testing
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // no special precondition
        bool reverted;
        try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        // In the original contract, only the owner (smartfix_owner) can succeed.
        // The test caller is not guaranteed to be the owner, so require that the call reverts
        // (this will be true for non-owners in the original and false in the mutant).
        assert(reverted);
    }
    receive() external payable {}
}

