contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // call as arbitrary msg.sender passed in; we assert that when caller is the owner, c's balance becomes zero
    function run(address payable caller) public payable {
        // must have some balance to observe destruction
        require(msg.value > 0, "send ETH");
        // fund the target contract
        (bool sent, ) = address(c).call{value: msg.value}("\x00");
        require(sent, "fund failed");

        // ensure caller equals the owner by reading public smartfix_owner getter
        address owner = c.smartfix_owner();
        require(owner == caller, "caller must be owner");

        // perform call as caller by using low-level call forwarding: the test itself must be the caller, so require caller==address(this)
        // instead we require the provided caller to be this contract to actually be the msg.sender for c.sudicideAnyone()
        require(caller == address(this), "caller must be this contract for actual call");

        // call the target function (this is the deciding call)
        c.sudicideAnyone();

        // after successful selfdestruct in original, c's balance should be zero
        assert(address(c).balance == 0);
    }

    // allow receiving ETH so this contract can fund c and be owner
    receive() external payable {}
}

