contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }

  // single test function: attempt to call sudicideAnyone from a caller-supplied address
  // We model different callers by using this contract as the caller; the caller identity
  // is represented by the relation between this contract and c.smartfix_owner() observed via the public getter.
  // The rule: call succeeds exactly when this contract is the owner.
  function check(bool expectOwner) public {
    // observe owner
    address owner = c.smartfix_owner();

    // precondition: expectOwner says whether this contract should be the owner
    // We require consistency between expectOwner and the actual equality to make the assertion meaningful
    require(expectOwner ? (owner == address(this)) : (owner != address(this)));

    // Attempt the call and capture whether it reverts. According to P, only the owner can succeed.
    bool success;
    // Using low-level call to detect whether c.sudicideAnyone succeeds without letting this test contract be destroyed
    (success, ) = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));

    // Assert that success happens exactly when this contract is the owner.
    assert(success == (owner == address(this)));
  }

  // Allow contract to receive ether if needed by external harnesses
  receive() external payable {}
}

