contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the caller address; we will ensure the caller is the stored owner by using the contract's stored owner getter
    function testFuzz_property(address caller) public {
        // keep caller non-zero to be sensible
        vm.assume(caller != address(0));

        // Fund the contract so selfdestruct has value to send
        vm.deal(address(this), 1 ether);
        // send ETH to contract
        (bool sent,) = address(c).call{value: 1 ether}("");
        require(sent);

        // read the stored owner from the contract
        address storedOwner = c.smartfix_owner();

        // We need the invoker to be the stored owner to allow the call to succeed.
        // If the fuzzed caller equals the stored owner, use it; otherwise, fuzz will still try other addresses
        // We will call sudicideAnyone as the stored owner using vm.prank
        vm.prank(storedOwner);

        bool ok;
        // call and catch any revert to produce a boolean we can assert about
        try c.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule the reference satisfies: after a successful call by the stored owner the contract balance is zero
        // We assert that either the call failed (ok == false) OR the contract balance is zero.
        // For the correct contract, when the stored owner calls it succeeds and address(c).balance == 0 for all inputs.
        // The mutant will fail this for some inputs (when recipient differs), so this assertion will fail on the mutant.
        assertTrue(!ok || address(c).balance == 0);
    }
}

