        vm.assume(actor != address(0));

        // ensure the contract has some balance so selfdestruct would have an effect
        vm.deal(address(c), 1 ether);

        // determine whether the caller is the stored owner
        address owner = c.smartfix_owner();

        // perform the call as the fuzzed actor and record whether it succeeded
        bool ok;
        vm.prank(actor);
        try c.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: the call succeeds iff actor == owner.
        // This must hold for the reference contract for all admissible inputs,
        // and a mutant that changes transfer target will still preserve who may call,
        // but we express the general rule as a single assert reading c's public getter.
        assertTrue(ok == (actor == owner));
    }
