pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameter: the caller address (the fuzzer will try many addresses)
    function testFuzz_property(address caller) public {
        // keep caller non-zero (admissible domain) but otherwise very wide
        vm.assume(caller != address(0));

        // fund the contract with some Ether so there's a balance to send on selfdestruct
        vm.deal(address(c), 1 ether);

        // make sure the saved owner is the deployer (setUp used msg.sender), so saved owner != caller
        // we only want the case where caller == smartfix_owner to exercise the universal property
        // therefore impersonate the saved owner when needed; saved owner is address(this) at setUp? No — setUp deployed c from this test contract.
        // In setUp we called `new C()` from this test contract, so smartfix_owner == address(this).
        // We fuzz `caller` and want to test the universal rule for any caller that equals the stored owner.

        // If the fuzzed caller equals the stored owner (address(this)), then the call should succeed and address(c).balance == 0.
        // If not, the call will revert; we only assert the universal rule when caller == stored owner.

        bool ok;
        // try to call sudicideAnyone as the fuzzed caller
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        try c.sudicideAnyone{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: if the caller equals the stored owner (address(this) from setUp), then the call must succeed
        // and the contract balance must be zero (selfdestruct sent funds to the caller). This is a universal rule for the reference
        // but the mutant that always targets smartfix_owner will fail this for some caller (when caller == stored owner? actually)
        // We express the rule as: (caller == saved owner) implies address(c).balance == 0 and the call succeeded.

        if (caller == address(this)) {
            // read only c's public surface: address(c).balance and the ok flag computed from the call
            assertTrue(ok && address(c).balance == 0);
        } else {
            // when caller != saved owner we do not assert anything (admissible domain includes all callers)
            assertTrue(true);
        }
    }
}
